// === Tab: mySketch ===
// WCCChallenge - "Shadow math"
// Another sketch featuring the Hilbert curve. Tried to do alternate the colors to simulate some "shading" in a spiral pattern, kind of a stretch :\

OPC.slider('hilbertNumber', 6, 3, 7, 1)
OPC.slider('lineWidth', 2, 0.5, 10, 0.5)
OPC.slider('spiralSpace', 40, 10, 100, 5)
OPC.slider('spiralDivisions', 16, 4, 30, 2)
OPC.slider('color1', 66, 0, 255, 1)
OPC.slider('color2', 225, 0, 255, 1)
OPC.slider('rotateSpeed', 50, 10, 100, 5)

function setup () {
	canvasWidth = canvasHeight = max(windowWidth, windowHeight)
  createCanvas(canvasWidth, canvasHeight)
  angleMode(DEGREES)
	background(bgColor)
	strokeCap(PROJECT)

	generateLines()
}

let cartToPolar = (x, y) => [sqrt(x*x+y*y), x === 0 ? 0 : atan(y/x)]

function draw () {
  background(bgColor)
  noFill()

  let cx = canvasWidth / 2, cy = canvasHeight / 2

  let divisions = spiralDivisions / 2
  let maxLength = dist(cx, cy, canvasWidth, canvasHeight)
  let n = ceil(maxLength / spiralSpace)
  let angle = 360 / divisions

	// Get the middle point. Calculate its polar position and color it according to the rotation and distance to the center
  for (let [i, [x1, y1, x2, y2]] of lines.entries()) {
    let px = ((x1 + x2) / 2), py = ((y1 + y2) / 2)
    let [r, theta] = cartToPolar(px - cx, py - cy)
    let _d = floor(r / spiralSpace)
    let _a = theta - _d * (frameCount / rotateSpeed)
    let section = fract(_a / angle)
    strokeWeight(lineWidth)
    stroke(section < 0.5 ? color1 : color2)
    line(x1, y1, x2, y2)
  }

}

let canvasWidth = 800, canvasHeight = 800
let ant, theCurve, iterations, iterStep
let lines = []
let bgColor = 200

// Taken from https://openprocessing.org/sketch/1396198
// Generates the lines for a Hilbert curve or order N (global hilbertNumber)
function generateLines () {
	iterations = hilbertNumber
	iterStep = 0
	lines = []
  ant = {
    x: 0,
    y: 0,
    stepSize: (min(canvasWidth, canvasHeight) - 20) / (2 ** iterations - 1),
    // stepSize: 10,
    movements: []
  }
  for(var j = 0; j < iterations; j++) {
    ant.movements = [...[...ant.movements].reverse().map((m)=>(m+1)%4),1,...ant.movements,0,...ant.movements,3,...[...ant.movements].reverse().map((m)=>(m+3)%4)];
  }

  for (let movement of ant.movements) {
    lines.push([
      ant.x + 10,
      ant.y + 10,
      ant.x + ant.stepSize * cos(movement * 90) + 10,
      ant.y + ant.stepSize * sin(movement * 90) + 10
    ])
    ant.x += ant.stepSize * cos(movement * 90)
    ant.y += ant.stepSize * sin(movement * 90)
  }
}

function parameterChanged (variableName, value) {
	if (variableName === 'hilbertNumber') {
		generateLines()
	}
}

function mousePressed() {
	let fs = fullscreen()
	fullscreen(!fs)
	canvasWidth = canvasHeight = max(windowWidth, windowHeight)
	generateLines()
}

